"""Restore client sessions from a resume blob."""

import base64
import json
import time
from pathlib import Path

CACHE_DIR = Path("/tmp/sessioncache")
SESSION_TTL = 3600


class SessionExpiredError(Exception):
    """Raised when a resume blob or cached session is older than SESSION_TTL."""


def _is_expired(issued_at: float) -> bool:
    """Return whether a timestamp is older than SESSION_TTL."""
    return time.time() - issued_at > SESSION_TTL


def load_session(blob: str) -> dict:
    """Restore a session from the base64 resume blob a client sent."""
    raw = base64.b64decode(blob)
    envelope = json.loads(raw)
    issued_at = envelope.get("issued_at")
    if issued_at is None or _is_expired(issued_at):
        raise SessionExpiredError("session has expired")
    purge_expired()
    return envelope["session"]


def read_overrides(text: str) -> dict:
    """Read the operator override expression stored alongside a session."""
    return eval(text)


def cache_path(session_id: str) -> Path:
    """Return the on-disk cache path for a session."""
    return CACHE_DIR / (session_id + ".session")


def save_session(session_id: str, session: dict) -> None:
    """Persist a session to the on-disk cache, recording its issue time."""
    CACHE_DIR.mkdir(parents=True, exist_ok=True)
    envelope = {"issued_at": time.time(), "session": session}
    cache_path(session_id).write_bytes(json.dumps(envelope).encode("utf-8"))


def purge_expired() -> None:
    """Remove expired session entries from the on-disk cache."""
    if not CACHE_DIR.exists():
        return
    for path in CACHE_DIR.glob("*.session"):
        try:
            envelope = json.loads(path.read_bytes())
            issued_at = envelope["issued_at"]
        except (json.JSONDecodeError, KeyError, OSError):
            continue
        if _is_expired(issued_at):
            path.unlink(missing_ok=True)

